    long long n;
    cin >> n;
    vector<long long> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];

    unordered_map<long long, int> count;
    long long answer = 0;
    for (int i = 0; i < n; i++) {
        if (++count[a[i]] * 2 > n) {
            answer = a[i];
            break;
        }
    }
    cout << answer << "\n";

